<div class="ido-logo"><img src="<?php echo esc_url(IDO_URL . 'assets/img/ido-logo.svg?ver=' . IDO_VERSION); ?>" width="600" height="600" alt="<?php echo esc_attr(IDO_Game::NAME); ?>" decoding="async"></div>
</div>
